DROP TABLE IF EXISTS `system_offers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `system_offers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `listing_id` int(11) NOT NULL,
  `card_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `league_id` int(11) NOT NULL,
  `offer_price` int(11) NOT NULL,
  `is_accepted` tinyint(1) DEFAULT NULL,
  `is_expired` tinyint(1) DEFAULT NULL,
  `offered_at` datetime DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `listing_id` (`listing_id`),
  KEY `card_id` (`card_id`),
  KEY `user_id` (`user_id`),
  KEY `league_id` (`league_id`),
  KEY `ix_system_offers_id` (`id`),
  CONSTRAINT `system_offers_ibfk_1` FOREIGN KEY (`listing_id`) REFERENCES `market_listings` (`id`),
  CONSTRAINT `system_offers_ibfk_2` FOREIGN KEY (`card_id`) REFERENCES `user_cards` (`id`),
  CONSTRAINT `system_offers_ibfk_3` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `system_offers_ibfk_4` FOREIGN KEY (`league_id`) REFERENCES `leagues` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
