--
-- Table structure for table `user_cards`
--

DROP TABLE IF EXISTS `user_cards`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `user_cards` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `player_id` int(11) NOT NULL,
  `team_id` int(11) DEFAULT NULL,
  `current_overall` int(11) NOT NULL,
  `is_tradeable` tinyint(1) DEFAULT NULL,
  `is_in_lineup` tinyint(1) DEFAULT NULL,
  `acquired_at` datetime DEFAULT NULL,
  `league_id` int(11) DEFAULT NULL,
  `protected_value` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `player_id` (`player_id`),
  KEY `team_id` (`team_id`),
  KEY `ix_user_cards_id` (`id`),
  CONSTRAINT `user_cards_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `user_cards_ibfk_2` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `user_cards_ibfk_3` FOREIGN KEY (`team_id`) REFERENCES `teams` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=281 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

